def can_chain(dominoes):
    """Return a list of dominoes forming a closed chain, or None if impossible.

    A valid chain uses every domino exactly once (each may be flipped),
    consecutive halves match, and the free ends of the first and last
    domino match each other.
    """
    if not dominoes:
        return []

    for i, domino in enumerate(dominoes):
        for first in (domino, (domino[1], domino[0])):
            rest = dominoes[:i] + dominoes[i + 1:]
            chain = _chain(rest, first[1], first[0], [first])
            if chain is not None:
                return chain
    return None


def _chain(rest, end, start, chain):
    """Try to extend `chain` (whose right end is `end`) using the dominoes
    in `rest`, requiring the final right end to equal `start`."""
    if not rest:
        return chain if end == start else None

    for i, domino in enumerate(rest):
        for placed in (domino, (domino[1], domino[0])):
            if placed[0] == end:
                result = _chain(
                    rest[:i] + rest[i + 1:],
                    placed[1],
                    start,
                    chain + [placed],
                )
                if result is not None:
                    return result
    return None

